//! RFC 1350 §5: every TFTP packet opens with a two-octet opcode. A Read or Write
//! Request (1, 2) is followed by NUL-terminated filename and mode strings; DATA
//! (3) and ACK (4) carry a two-octet block number; ERROR (5) carries a two-octet
//! code and a NUL-terminated message. The strings are not at a fixed offset, so
//! they are decoded into the item list rather than placed in the field table.
//!
//! Generated by dev/protogen from dev/protogen/specs/tftp.toml. Field layouts
//! come from the RFC cited above; edit the spec, not this file.

use crate::field::FieldDesc;
use crate::proto::{ProtoDesc, ProtoId};

// protogen:hand begin
use crate::layers::text;
use crate::options::Item;

fn op(hdr: &[u8]) -> u16 {
    match hdr.get(0..2) {
        Some(b) => u16::from_be_bytes([b[0], b[1]]),
        None => 0,
    }
}

fn has_block(hdr: &[u8]) -> bool {
    matches!(op(hdr), 3 | 4)
}

fn is_error(hdr: &[u8]) -> bool {
    op(hdr) == 5
}

/// DATA (3) is followed by the data itself; the request and error forms are
/// NUL-terminated strings that run to the end of the datagram.
fn header_len(hdr: &[u8]) -> usize {
    match op(hdr) {
        3 | 4 => 4,
        1 | 2 | 5 => hdr.len(),
        _ => 2,
    }
}

fn parse_options(hdr: &[u8]) -> Vec<Item> {
    let mut out = Vec::new();
    match op(hdr) {
        1 | 2 => {
            for (i, s) in hdr
                .get(2..)
                .unwrap_or(&[])
                .split(|c| *c == 0)
                .take(2)
                .enumerate()
            {
                if !s.is_empty() {
                    out.push(text::item(
                        if i == 0 { "filename" } else { "mode" },
                        i as u32,
                        s,
                    ));
                }
            }
        }
        5 => {
            let m = hdr.get(4..).unwrap_or(&[]);
            out.push(text::named(
                "errormsg",
                m.split(|c| *c == 0).next().unwrap_or(&[]),
            ));
        }
        _ => {}
    }
    out
}
// protogen:hand end

pub static FIELDS: &[FieldDesc] = &[
    FieldDesc::uint("op", 0, 16, 1),
    FieldDesc::uint("block", 16, 16, 0).when(has_block),
    FieldDesc::uint("errorcode", 16, 16, 0).when(is_error),
    FieldDesc::var_bytes("options", 32),
];

pub static DESC: ProtoDesc = ProtoDesc {
    id: ProtoId::Tftp,
    name: "TFTP",
    fields: FIELDS,
    min_len: 2,
    header_len,
    next: crate::proto::next_raw,
    build_len: 2,
    parse_options: Some(parse_options),
    opt_table: None,
    set_hlen: None,
    bind_next: None,
    bind_next_bytes: None,
    content_len: None,
};

#[cfg(test)]
mod tests {
    #![allow(unused_imports)]
    use super::*;
    use crate::field::FieldValue;
    use crate::packet::Packet;

    // protogen:tests begin
    /// RFC 1350 §5 read request for "a" in octet mode.
    fn vector() -> Vec<u8> {
        vec![0x00, 0x01, 0x61, 0x00, 0x6f, 0x63, 0x74, 0x65, 0x74, 0x00]
    }

    #[test]
    fn dissects_the_rfc_vector() {
        let p = Packet::dissect(vector(), ProtoId::Tftp);
        let l = p.find_layer(ProtoId::Tftp).unwrap();
        assert_eq!(p.get(l, "op").unwrap(), FieldValue::Uint(1));
        assert_eq!(p.raw_bytes(), &vector()[..]);
    }

    #[test]
    fn truncation_does_not_panic() {
        for n in 0..vector().len() {
            let p = Packet::dissect(vector()[..n].to_vec(), ProtoId::Tftp);
            assert_eq!(p.raw_bytes(), &vector()[..n]);
        }
    }

    #[test]
    fn writes_survive_a_rebuild() {
        let mut p = Packet::dissect(vector(), ProtoId::Tftp);
        let l = p.find_layer(ProtoId::Tftp).unwrap();
        let n = p.raw_bytes().len();
        for f in crate::proto::active_fields(ProtoId::Tftp, false, p.header(l))
            .filter(|f| f.kind == crate::field::FieldKind::Uint && f.bit_len <= 32)
            .map(|f| f.name)
            .collect::<Vec<_>>()
        {
            p.set_uint(l, f, 1);
        }
        assert_eq!(p.to_bytes().len(), n);
    }
    // protogen:tests end
}
